@push('scripts')<script>function pos(catalog,type){return{catalog,type,search:'',category:'',cart:[],customer:'',payments:{},token:'{{ \Illuminate\Support\Str::uuid() }}',submitting:false,get filtered(){let s=this.search.toLowerCase();return this.catalog.filter(x=>(!this.category||String(x.category_id)===this.category)&&(!s||`${x.name} ${x.sku} ${x.barcode||''} ${x.remnant_no||''} ${x.colour||''}`.toLowerCase().includes(s)))},addFirst(){if(this.filtered[0])this.add(this.filtered[0])},available(item,u){return u?Number(item.stock/u.rate).toFixed(3):0},add(item){let u=item.units[0];if(!u)return;let key=item.key+'-'+u.unit_id,found=this.cart.find(x=>x.lineKey===key);if(found&&type==='main'){found.quantity+=1;return}this.cart.push({...item,lineKey:key,unit_id:u.unit_id,quantity:type==='remnant'?item.display_qty:1,price:u.price,discount:0,maxDisplay:Number(item.stock/u.rate).toFixed(6)})},unitChanged(line){let u=line.units.find(x=>x.unit_id==line.unit_id);line.price=u.price;line.maxDisplay=Number(line.stock/u.rate).toFixed(6);line.lineKey=line.key+'-'+u.unit_id},lineTotal(l){return Math.max(0,(Number(l.quantity)||0)*(Number(l.price)||0)-(Number(l.discount)||0))},get subtotal(){return this.cart.reduce((s,l)=>s+(Number(l.quantity)||0)*(Number(l.price)||0),0)},get discount(){return this.cart.reduce((s,l)=>s+(Number(l.discount)||0),0)},get total(){return Math.max(0,this.subtotal-this.discount)},get paid(){return Object.values(this.payments).reduce((s,v)=>s+(Number(v)||0),0)},get due(){return Math.max(0,this.total-this.paid)},money(v){return Number(v||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}}}</script>@endpush @endsection
